#!/usr/bin/env bash
# Generate xz test fixtures under testdata/xz/ using system xz 5.8.3.
#
# Reproducible: xz embeds no mtime, so `xz -9` output is byte-stable.
set -euo pipefail

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
XZDIR="$SCRIPT_DIR/../xz"
mkdir -p "$XZDIR"
OUT="$(cd "$XZDIR" && pwd)"
cd "$OUT"
rm -f ./*.xz ./*.txt

XZ_BIN="${XZ_BIN:-xz}"

printf 'Hello, hajizip!\n' > hello.txt
"$XZ_BIN" -9 -c hello.txt > hello.txt.xz

# Multi-stream: two concatenated xz streams.
cp hello.txt.xz multi-stream.xz
cat hello.txt.xz >> multi-stream.xz

# Corrupt: truncate the stream (drop the final 16 bytes: footer + index).
head -c $(( $(stat -c %s hello.txt.xz) - 16 )) hello.txt.xz > corrupt-truncated.xz

# Corrupt: flip a byte in the LZMA2 payload.
cp hello.txt.xz corrupt-flip.xz
OFF=$(( $(stat -c %s hello.txt.xz) / 2 ))
printf '\xff' | dd of=corrupt-flip.xz bs=1 seek="$OFF" conv=notrunc 2>/dev/null

# --- manifest -----------------------------------------------------------------
cat > manifest.toml <<'EOF'
# xz fixtures. Generated by testdata/gen/gen-xz.sh (xz 5.8.3, level 9).

[hello.txt.xz]
note = "xz -9 of hello.txt ('Hello, hajizip!\\n'), byte-stable"

[multi-stream.xz]
note = "two concatenated xz streams"

[corrupt-truncated.xz]
note = "stream missing its footer/index"

[corrupt-flip.xz]
note = "byte flipped inside the LZMA2 payload"
EOF

echo "generated:"
ls -l ./*.xz ./*.txt
